-- PHY 101 Exam Sprint: import 200 reviewed MCQs into an empty bank
-- Sources: PHY 101 NOTE (1).docx; downloadfile (4).pdf; standard General Physics I enrichment
-- The script creates the private bank if none exists and refuses to overwrite existing questions.
BEGIN;

DO $import$
DECLARE
  v_set_id uuid;
  v_set_count integer;
  v_question jsonb;
  v_option jsonb;
BEGIN
  SELECT count(*) INTO v_set_count
  FROM public.study_quiz_sets
  WHERE upper(regexp_replace(coalesce(course_code, ''), '[^A-Za-z0-9]', '', 'g')) = 'PHY101'
    AND delivery_mode = 'mock_exam'
    AND exam_campaign_key = 'supplementary-2026';

  IF v_set_count = 0 THEN
    INSERT INTO public.study_quiz_sets
      (title, description, course_code, level, semester, difficulty, time_limit_minutes,
       questions_count, published, visibility, source, delivery_mode, exam_campaign_key,
       access_tier, exam_question_count, diagnostic_question_count, diagnostic_time_limit_minutes)
    VALUES
      ('PHY 101 Exam Sprint Mock',
       'Private PHY 101 Exam Sprint bank covering supplied mechanics notes and General Physics I.',
       'PHY 101', '100', 'first', 'hard', 40,
       0, false, 'private', 'exam_sprint', 'mock_exam', 'supplementary-2026',
       'plus_monthly', 40, 10, 10)
    RETURNING id INTO v_set_id;
  ELSIF v_set_count = 1 THEN
    SELECT id INTO v_set_id
    FROM public.study_quiz_sets
    WHERE upper(regexp_replace(coalesce(course_code, ''), '[^A-Za-z0-9]', '', 'g')) = 'PHY101'
      AND delivery_mode = 'mock_exam'
      AND exam_campaign_key = 'supplementary-2026'
    LIMIT 1;
  ELSE
    RAISE EXCEPTION 'More than one PHY 101 Exam Sprint bank exists. Keep one target bank before importing.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.study_quiz_questions
    WHERE coalesce(set_id, quiz_set_id) = v_set_id
  ) THEN
    RAISE EXCEPTION 'The PHY 101 target bank already contains questions. Import stopped to prevent duplicates.';
  END IF;

  FOR v_question IN
    SELECT value FROM jsonb_array_elements($phy101_questions$[{"id":"197088ba-d190-525f-9987-c73b3b564505","position":0,"prompt":"Which of the following is an SI base quantity?","explanation":"Electric current is a base quantity; force, pressure and energy are derived quantities.","questionKind":"recall","difficulty":"easy","cognitive":"recall","topic":"Measurements, Units and Dimensions","fingerprint":"d8768c35653d9323d03201ee997d55c9671b1dcf877bcdceba727d1f9de1b59e","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 1","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 1","scientificallyCrossChecked":true},"options":[{"id":"35e4fdf5-1b38-5a0c-9783-8c28461b65a7","text":"Electric current","isCorrect":true,"position":0},{"id":"5847e2e1-5b00-5c16-b97b-763c6fa878d3","text":"Force","isCorrect":false,"position":1},{"id":"c4784ebb-85b9-5f3d-b53d-ffcb060114be","text":"Pressure","isCorrect":false,"position":2},{"id":"1d3a751f-4a27-57e1-8185-8930a0eecef9","text":"Energy","isCorrect":false,"position":3}]},{"id":"15fcce96-0f52-53d7-be46-489e08828485","position":1,"prompt":"What is the SI unit of luminous intensity?","explanation":"The candela is the SI base unit of luminous intensity.","questionKind":"recall","difficulty":"easy","cognitive":"recall","topic":"Measurements, Units and Dimensions","fingerprint":"10b5842137496d27064815be0c6d6039e91df9082ace31a0fc581ead51c4e9a8","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 1","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 1","scientificallyCrossChecked":true},"options":[{"id":"36de2146-1182-54bf-b670-2e78a05ff799","text":"lumen","isCorrect":false,"position":0},{"id":"1490668d-6eb9-54bc-8c71-fac17fd2cd9b","text":"lux","isCorrect":false,"position":1},{"id":"63f6e7c8-09e4-585a-9c78-8fb13e