ion":1},{"id":"5d2a3a16-2557-5d88-9d19-e59cc0996327","text":"ML²T⁻²","isCorrect":false,"position":2},{"id":"d92c212e-97bc-5100-befd-700c893011c1","text":"MLT⁻¹","isCorrect":false,"position":3}]},{"id":"0169632f-7850-587a-98c0-0f88cba7408f","position":4,"prompt":"Which pair contains only derived quantities?","explanation":"Velocity and pressure are obtained from combinations of base quantities.","questionKind":"concept","difficulty":"medium","cognitive":"application","topic":"Measurements, Units and Dimensions","fingerprint":"5aa32e6e7c9fb496f40128d549bec51917fee0c185a6fd0222fe8f249b361941","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 1","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 1","scientificallyCrossChecked":true},"options":[{"id":"fdb46525-33a3-5f75-9483-8a6d9d53955d","text":"velocity and pressure","isCorrect":true,"position":0},{"id":"fa4692c3-7aa0-5b39-973b-ec33a6fbf01d","text":"mass and time","isCorrect":false,"position":1},{"id":"8471717e-34aa-53be-8d0b-a5c9e99aab6d","text":"length and temperature","isCorrect":false,"position":2},{"id":"546563e0-e7f4-5bb4-983b-78bfed8f5bee","text":"current and amount of substance","isCorrect":false,"position":3}]},{"id":"80c72943-2b46-5837-a016-c3f75c51e7ca","position":5,"prompt":"Dimensional analysis can directly be used to do which of the following?","explanation":"Dimensional analysis checks consistency of dimensions but cannot determine all constants or vector character.","questionKind":"concept","difficulty":"medium","cognitive":"application","topic":"Measurements, Units and Dimensions","fingerprint":"36deb5b0f598927ae91cb50ac91f2521d46663e3a3819da4a53903141bd9429a","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 1","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 1","scientificallyCrossChecked":true},"options":[{"id":"c1396518-b718-56e7-82da-6afda333d91d","text":"Determine every numerical constant in a formula","isCorrect":false,"position":0},{"id":"ea228b8d-671f-516a-a0d3-fa3bb532604d","text":"Decide whether a quantity is scalar or vector","isCorrect":false,"position":1},{"id":"895f8345-f2bd-5ac3-ad69-cbba1858b62d","text":"Prove that an experimental result is exact","isCorrect":false,"position":2},{"id":"e7cee7ba-496a-593a-81b5-7ccfe1872035","text":"Check whether an equation is dimensionally homogeneous","isCorrect":true,"position":3}]},{"id":"73662dc5-dc04-5bc4-8d54-8adfa9223616","position":6,"prompt":"Why can dimensional analysis not distinguish work from torque?","explanation":"Both work and torque have dimensions ML²T⁻² even though they represent different physical ideas.","questionKind":"concept","difficulty":"medium","cognitive":"application","topic":"Measurements, Units and Dimensions","fingerprint":"1b22052b13398b14ead8caa12380940db392ebff595d36fb7732d5cd281698bc","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 1","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 1","scientificallyCrossChecked":true},"options":[{"id":"a436761e-397d-5108-95d3-31e62d473acf","text":"Torque has no dimensions","isCorrect":false,"position":0},{"id":"21cccd5e-9c8d-5089-8253-a8ec96241d50","text":"Work is a base quantity","isCorrect":false,"position":1},{"id":"653f500a-2ef8-5831-8498-d935ed439eeb","text":"They have the same dimensions","isCorrect":true,"position":2},{"id":"62b3c400-82d5-5db7-bd48-bf6e55714bfd","text":"They have different SI units","isCorrect":false,"position":3}]},{"id":"7c96a6c8-d9d5-5eea-8385-1d00c20c695f","position":7,"prompt":"What is the SI unit of pressure?","explanation":"Pressure is force per unit area, so its unit is N/m², also called the pascal.","questionKind":"recall","difficulty":"easy","c