ked":true},"options":[{"id":"47e5de23-ce6b-5455-8fa6-2916139ba4fc","text":"ML⁻¹T⁻²","isCorrect":false,"position":0},{"id":"24fb25cf-fdac-5938-babc-ade3f0b2f80f","text":"ML²T⁻²","isCorrect":false,"position":1},{"id":"f78ea856-24a8-5ce4-86ad-89a9b259af49","text":"MT⁻²","isCorrect":true,"position":2},{"id":"2e2e90a1-2b32-5ab6-a6d3-64c2cf4495a3","text":"MLT⁻²","isCorrect":false,"position":3}]},{"id":"31cfcada-3dd3-5a63-8aa4-50d5d99704fa","position":15,"prompt":"If the measured radius of a circle has a 2% uncertainty, what is the approximate percentage uncertainty in its area?","explanation":"Area is proportional to r², so the fractional uncertainty is approximately doubled.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Measurements, Units and Dimensions","fingerprint":"45526f1a9296963c642e0039ad25eb61ce2b407b1eeda49d259c31a1de66e6e3","studyRef":{"sourceLabel":"General PHY 101 enrichment: measurement and dimensional analysis","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: measurement and dimensional analysis","scientificallyCrossChecked":true},"options":[{"id":"e15d03fb-f9a2-541a-a784-af75cf6b55c8","text":"8%","isCorrect":false,"position":0},{"id":"7396203a-d62a-5a93-a7a7-948b918e17d8","text":"4%","isCorrect":true,"position":1},{"id":"918850c1-c1e5-5c7c-a18a-5e60f5cb967b","text":"1%","isCorrect":false,"position":2},{"id":"176374f1-2d55-5b0e-aa97-38382c80da2e","text":"2%","isCorrect":false,"position":3}]},{"id":"c4837504-42d8-5550-8cb9-56f1fbb12fdb","position":16,"prompt":"What are the dimensions of the gravitational constant G?","explanation":"From F = Gm₁m₂/r², G = Fr²/(m₁m₂), giving M⁻¹L³T⁻².","questionKind":"calculation","difficulty":"hard","cognitive":"analysis","topic":"Measurements, Units and Dimensions","fingerprint":"8ce399a035f20d06d4a0dde1ddf4e72b76f17e51ba981e216a366b1e75bcffd4","studyRef":{"sourceLabel":"Gener