al point are significant.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Measurements, Units and Dimensions","fingerprint":"2571076f1ccde874eb168a8a71c538e78a09d75aee726974769cf3e52dc6908a","studyRef":{"sourceLabel":"General PHY 101 enrichment: measurement and dimensional analysis","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: measurement and dimensional analysis","scientificallyCrossChecked":true},"options":[{"id":"179d3bd7-a300-5031-9224-503c6bebc800","text":"3","isCorrect":false,"position":0},{"id":"3bf44f0d-fbcf-59bb-8f40-a28cdf363105","text":"5","isCorrect":false,"position":1},{"id":"acf0a926-ede3-5c3e-9514-6e31b22f89d3","text":"4","isCorrect":true,"position":2},{"id":"5ddf7761-d4e6-5da2-9098-004651d68983","text":"2","isCorrect":false,"position":3}]},{"id":"17203d1c-0992-5a9d-bd6d-4a44e782b0b1","position":19,"prompt":"Which instrument is most suitable for measuring the diameter of a thin wire accurately?","explanation":"A micrometer screw gauge has the small least count needed for a thin wire.","questionKind":"application","difficulty":"easy","cognitive":"recall","topic":"Measurements, Units and Dimensions","fingerprint":"b2f9cde73ec9415fe50efa43ae3632990be3b9b50510dc09012b4477203be8c4","studyRef":{"sourceLabel":"General PHY 101 enrichment: measurement and dimensional analysis","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: measurement and dimensional analysis","scientificallyCrossChecked":true},"options":[{"id":"073f24e1-8198-561b-a350-50ec4a553e14","text":"spring balance","isCorrect":false,"position":0},{"id":"159d36d0-9b7f-59d4-881d-17e5a4c022da","text":"micrometer screw gauge","isCorrect":true,"position":1},{"id":"786f0bfc-22b1-508e-a0ce-652a27900c04","text":"metre rule","isCorrect":false,"position"