":1},{"id":"e2da638f-3e5f-50d3-b42d-9f71dae2af90","text":"force","isCorrect":false,"position":2},{"id":"d3f70cde-65ea-5d4f-815f-3d5820d8d911","text":"torque","isCorrect":true,"position":3}]},{"id":"aa129054-dfb5-53b4-9fc3-6f43d3fc30f1","position":22,"prompt":"What does the length of an arrow representing a vector indicate?","explanation":"In a scaled vector diagram, arrow length represents magnitude while its direction represents direction.","questionKind":"recall","difficulty":"easy","cognitive":"recall","topic":"Vectors and Scalars","fingerprint":"e1c8fc976b97af21caac463369116e25a25d97ba575e873e9b8a30d70c2cbcfa","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 2","scientificallyCrossChecked":true},"options":[{"id":"1cdae8a8-a864-55a8-ab8b-a75f27b1605c","text":"the origin of coordinates","isCorrect":false,"position":0},{"id":"4a6f2c9f-c231-5fe7-be59-40e65fa1d97b","text":"the mass of the object","isCorrect":false,"position":1},{"id":"65627c2c-313a-5f59-a870-d3b6e3f00028","text":"the vector's magnitude","isCorrect":true,"position":2},{"id":"ec28d8fb-bffd-5618-849f-1723b0302e00","text":"the vector's unit only","isCorrect":false,"position":3}]},{"id":"6e858bae-127a-5087-b80a-2ee50d6840ec","position":23,"prompt":"When two vectors are added by the triangle law, the resultant is drawn from where to where?","explanation":"After placing the second vector head-to-tail, the resultant joins the initial tail to the final head.","questionKind":"concept","difficulty":"medium","cognitive":"application","topic":"Vectors and Scalars","fingerprint":"5918795e2bb125a58598b1cfa4a1ced0d55896e86511730048cc401d7e3c10e0","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 1