":"recall","difficulty":"easy","cognitive":"recall","topic":"Vectors and Scalars","fingerprint":"53bef3913a554436b2e91cd1ea29f4d7f383844c828ddb55fb5e3bd6b81792ed","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 2","scientificallyCrossChecked":true},"options":[{"id":"95e32054-9d8f-5ab1-9d11-6b3e76a15530","text":"dependent on its direction","isCorrect":false,"position":0},{"id":"da15dfe7-11df-5d5b-85af-bb3d38e346aa","text":"1","isCorrect":true,"position":1},{"id":"14c1512d-d089-5cef-895c-a9c4df5c304a","text":"0","isCorrect":false,"position":2},{"id":"dd683c22-df9f-5b68-bd45-25734623f5ad","text":"π","isCorrect":false,"position":3}]},{"id":"ab782e7f-84fd-5365-811c-9ce1292e13d4","position":28,"prompt":"If a particle returns to its starting point, what is its displacement?","explanation":"Displacement depends only on initial and final positions, which are identical here.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Vectors and Scalars","fingerprint":"06620b32a7cc28e574a1bdeaf423efbd1b121054d23bf51a0b0f98d6433fce9d","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 2","scientificallyCrossChecked":true},"options":[{"id":"912160e8-dffe-5894-9b51-45877162411f","text":"zero","isCorrect":true,"position":0},{"id":"bb9d2789-00c2-5122-82d9-cb65acffaa52","text":"equal to the total distance","isCorrect":false,"position":1},{"id":"2b456ec8-4708-55da-8071-9371cba5633d","text":"always negative","isCorrect":false,"position":2},{"id":"f1741614-fe7c-596c-b79a-fe909b49f26e","text":"equal to its speed","isCorrect":false,"position":3}]},{"id":"eb585b43-a40c-5db8-9fb3-4651a03aba6e","position":29,"prompt":"Two equal vectors act in exactly opposite directions. What is their resultant?","explanation":"Equal and opposite vectors cancel.","questionKind":"application","difficulty":"easy","cognitive":"recall","topic":"Vectors and Scalars","fingerprint":"21266f574c6129b793610f4f8ff3da5e3316f80f3dc8b3b8dfda8ffff46a64a8","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 2","scientificallyCrossChecked":true},"options":[{"id":"6f4c7bcf-8a0a-5382-a224-877dd65a9b86","text":"twice either vector","isCorrect":false,"position":0},{"id":"70c4d5b3-4ee5-52aa-98e4-93a85aea1adc","text":"equal to either vector","isCorrect":false,"position":1},{"id":"0a8c2b52-7de0-55c2-b675-84c3427f7212","text":"a vector perpendicular to both","isCorrect":false,"position":2},{"id":"e7e3ec8f-d804-5280-b43d-340f9a19d83b","text":"zero","isCorrect":true,"position":3}]},{"id":"d6560ba2-3cb0-5ed7-b55f-8ee072720f2b","position":30,"prompt":"What is the magnitude of the vector 3i + 4j?","explanation":"Magnitude = √(3² + 4²) = 5.","questionKind":"calculation","difficulty":"easy","cognitive":"recall","topic":"Vectors and Scalars","fingerprint":"a7fa79773e2f347bc5e400ba7467a462e3e546763e5f2a092587dbb05bf55a00","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 2","scientificallyCrossChecked":true},"options":[{"id":"7307aab6-d997-5aa0-a0e3-2e8331a03ec1","text":"7","isCorrect":false,"position":0},{"id":"504faf1e-0507-589e-8900-1aad2f4143dc","text":"25","isCorrect":false,"position":1},{"id":"e3055f86-3408-5abb-b5e3-b962935449d7","text":"5","isCorrect":true,"position":2},{"id":"fbe88555-c544-5199-a286-a5b02b4cb117","text":"1","isCorrect":false,"position":3}]},{"id":"505af992-1e06-5cbe-bdb9-d8b2473f6f56","position":31,"prompt":"A 10 N force acts at 60° to the positive x-axis. What is its x-component?","explanation":"Fx = F cos 60° = 10 × 0.5 = 5 N.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Vectors and Scalars","fingerprint":"d1ea5e3145b2d450d2b58322eca23464cca2ce968d82858e0fb54192ac01e09a","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 2","scientificallyCrossChecked":true},"options":[{"id":"82df9e6b-046f-5e6d-a5c7-53f02f4e6a40","text":"20 N","isCorrect":false,"position":0},{"id":"8f277f62-5029-5e67-9a76-9f39eff802a0","text":"5 N","isCorrect":true,"position":1},{"id":"3af4b245-33c9-595d-93a0-6b715eb3843f","text":"8.66 N","isCorrect":false,"position":2},{"id":"c7c4d744-4cd0-577f-a080-1538c5157d77","text":"10 N","isCorrect":false,"position":3}]},{"id":"701ca369-527c-564a-a245-62af3bedf611","position":32,"prompt":"A vector has components 6 m east and 8 m north. What is its magnitude?","explanation":"Magnitude = √(6² + 8²) = 10 m.","questionKind":"calculation","difficulty":"easy","cognitive":"recall","topic":"Vectors and Scalars","fingerprint":"247a710eb4907d516723145e4591d1df55ce01817dcc0c46986f994bcbc24200","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 2","scientificallyCrossChecked":true},"options":[{"id":"0870239c-955b-5834-8430-3dcd9ee15cdb","text":"10 m","isCorrect":true,"position":0},{"id":"0f904b92-fc3e-55ec-9e9b-58d53acaf9bf","text":"2 m","isCorrect":false,"position":1},{"id":"af222a81-4e05-5a5d-aba6-2d6a8eaf1869","text":"14 m","isCorrect":false,"position":2},{"id":"e4ca9227-260b-51f3-b596-51990323d670","text":"48 m","isCorrect":false,"position":3}]},{"id":"5f6803fd-7534-5597-9dd1-d2216af70b59","position":33,"prompt":"For A = 2i + 3j and B = 4i − j, what is A·B?","explanation":"A·B = (2)(4) + (3)(−1) = 8 − 3 = 5.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Vectors and Scalars","fingerprint":"810b2670c1ef7ed9ae28a18d296efbd3afb6e0212d72fb9e0d576c1d68042929","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 2","scientificallyCrossChecked":true},"options":[{"id":"c8b36036-e60f-541a-9e79-fb1eae44f5ba","text":"7","isCorrect":false,"position":0},{"id":"f1e7ad5b-41bc-5905-869c-6def799707dc","text":"8","isCorrect":false,"position":1},{"id":"c608d0e6-82bb-59eb-87e4-bd4aa182081e","text":"11","isCorrect":false,"position":2},{"id":"89f31965-464e-5c5d-b462-2018f0bfa6d7","text":"5","isCorrect":true,"position":3}]},{"id":"c74b5378-94b5-5c53-86ba-c511b224e5c4","position":34,"prompt":"Two perpendicular forces of 5 N and 12 N act at a point. What is the magnitude of their resultant?","explanation":"For perpendicular vectors, R = √(5² + 12²) = 13 N.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Vectors and Scalars","fingerprint":"900cd41d1eed8648dc14f1f83dac11c3f3cd0a9f9528df9ba52357cc83a92d2c","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 2","scientificallyCrossChecked":true},"options":[{"id":"13c3e400-e24a-53b6-be5a-50d9a74b6a87","text":"17 N","isCorrect":false,"position":0},{"id":"76869d3f-5074-5416-9a0c-e642c369aa39","text":"60 N","isCorrect":false,"position":1},{"id":"620c8e7d-8817-52a8-b44e-905ee2382c13","text":"13 N","isCorrect":true,"position":2},{"id":"b8b6e9de-8ad9-543b-a4be-50