rceReference":"PHY 101 NOTE (1), Study Sessions 5 and 6","scientificallyCrossChecked":true},"options":[{"id":"3be04c63-e3b5-5651-83ed-4554538b5b5c","text":"kg m⁻²","isCorrect":false,"position":0},{"id":"011417a5-3e54-5896-938f-40b1f2643986","text":"J s⁻¹","isCorrect":false,"position":1},{"id":"0125e21f-511a-5b44-a1ca-481bae006cfb","text":"N s","isCorrect":true,"position":2},{"id":"3374ff66-1fa0-554d-8a4b-c3206b3db2b9","text":"N s⁻¹","isCorrect":false,"position":3}]},{"id":"68208581-675a-58d9-99b2-f323db6883ba","position":83,"prompt":"Why does an airbag reduce the average force on a passenger during a collision?","explanation":"For a fixed change in momentum, increasing impact time reduces average force.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Impulse, Momentum and Centre of Mass","fingerprint":"86aeaf9368d992e1d79b33931126ea829e01202dfd201ccd4626143d759d7634","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Sessions 5 and 6","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Sessions 5 and 6","scientificallyCrossChecked":true},"options":[{"id":"4afe814d-404a-566c-ae3c-7b68179399e6","text":"It makes the collision perfectly elastic","isCorrect":false,"position":0},{"id":"6884be58-fc0f-5949-beff-9989064a3f9f","text":"It increases the time over which momentum changes","isCorrect":true,"position":1},{"id":"f9a144f2-164a-567a-9440-bd0054021e64","text":"It increases the passenger's momentum","isCorrect":false,"position":2},{"id":"e938028d-01bf-5e32-8c26-9799942297f4","text":"It removes the passenger's mass","isCorrect":false,"position":3}]},{"id":"49df1dac-7404-5235-97a1-98d2aa41ee8b","position":84,"prompt":"In an isolated system, total linear momentum remains constant provided what is zero?","explanation":"Momentum is conserved when external impulse is zero.","questionKind":"concept","difficulty":"medium","cognitive":"application","topic":"Impulse, Momentum and Centre of Mass","fingerprint":"b014e45dd6589be92619f9b27319f5fc57f03f1286f0d71351d519465bf9bf93","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Sessions 5 and 6","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Sessions 5 and 6","scientificallyCrossChecked":true},"options":[{"id":"f14a869e-b2dd-5ad8-bf1a-89eba8a923f1","text":"The net external force","isCorrect":true,"position":0},{"id":"d60ec08f-fb94-5d10-b24b-3b2e62d0cde5","text":"The internal forces","isCorrect":false,"position":1},{"id":"ccdb6f85-3e78-5e51-ac25-b81c2c74eab2","text":"The total kinetic energy","isCorrect":false,"position":2},{"id":"9232e15e-c4a3-5477-8f9c-1755260256e6","text":"The mass of every object","isCorrect":false,"position":3}]},{"id":"a4b7aa33-8d21-57fe-bd10-a31b5cf5a545","position":85,"prompt":"In a perfectly inelastic collision, the colliding objects do what after impact?","explanation":"Perfectly inelastic objects stick together while total momentum remains conserved.","questionKind":"concept","difficulty":"medium","cognitive":"application","topic":"Impulse, Momentum and Centre of Mass","fingerprint":"4946f0a420f62a4773f958395d3f779e39a469ec17499b6990aeac81e0f3e119","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Sessions 5 and 6","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Sessions 5 and 6","scientificallyCrossChecked":true},"options":[{"id":"4ed4b78e-5cc3-584f-8eca-2ddcf019c40a","text":"Exchange velocities in every case","isCorrect":false,"position":0},{"id":"5beb85b0-cbeb-59a9-ae69-d36b703de79a","text":"Return with unchanged speeds","isCorrect":false,"position":1},{"id":"208c0778-5bb4-5f2d-a213-79f0314e075f","text":"Lose all momentum","isCorrect":false,"position":2},{"id":"706f4168-1caf-56e7-bcd3-5259038d6a6c","text":"Move together","isCorrect":true,"position":3}]},{"id":"d034b94b-95fd-5f5b-99f3-ad2726096480","position":86,"prompt":"Which quantity is conserved in both elastic and inelastic collisions of an isolated system?","explanation":"Momentum is conserved in both; kinetic energy is conserved only in an elastic collision.","questionKind":"concept","difficulty":"medium","cognitive":"application","topic":"Impulse, Momentum and Centre of Mass","fingerprint":"9f11820fcd50b42e2d39e9a31682dc1a74fd186494a3e2430dbbecea0293ce61","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Sessions 5 and 6","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Sessions 5 and 6","scientificallyCrossChecked":true},"options":[{"id":"9bedcaf9-d6c6-5860-a9a3-b3f3fd928685","text":"mechanical power","isCorrect":false,"position":0},{"id":"fda6774e-7bcf-56ed-be78-02aa0307c3da","text":"relative speed","isCorrect":false,"position":1},{"id":"dc8935d4-d9eb-584c-927c-bc50e4d823dd","text":"linear momentum","isCorrect":true,"position":2},{"id":"29a01937-e75a-5d7c-9814-467cbe927cfe","text":"kinetic energy","isCorrect":false,"position":3}]},{"id":"5f304924-bca0-565d-8e72-bf65037984b9","position":87,"prompt":"The recoil of a gun is best explained by conservation of what?","explanation":"Forward bullet momentum is balanced by backward gun momentum.","questionKind":"application","difficulty":"easy","cognitive":"recall","topic":"Impulse, Momentum and Centre of Mass","fingerprint":"8b092dd4f462d35835672369c06fcb4bc2c4a29108ecc6b816bda803eb7cec3b","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Sessions 5 and 6","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Sessions 5 and 6","scientificallyCrossChecked":true},"options":[{"id":"5879b26f-70dd-5447-86b8-7c86201efbe6","text":"electric charge only","isCorrect":false