,"fingerprint":"41c90e288f7efe76d3335c648b93ac2123ed5b19bd1f295e6e80f5e42ea884fe","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Sessions 5 and 6","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Sessions 5 and 6","scientificallyCrossChecked":true},"options":[{"id":"5bc1389c-4a95-57ed-b9a9-0acb4e9615e7","text":"250 N s","isCorrect":false,"position":0},{"id":"d3895210-c99d-5e49-87c2-669f5b116834","text":"10 N s","isCorrect":true,"position":1},{"id":"634b0d9b-c058-55b5-87c2-2b4f2b94691c","text":"0.25 N s","isCorrect":false,"position":2},{"id":"9559824f-4af0-5ce5-8ed6-d80b33c301f3","text":"50 N s","isCorrect":false,"position":3}]},{"id":"943e4aa7-58ff-5d6b-b99b-f44a0f20be7c","position":92,"prompt":"A 0.5 kg ball initially at rest receives an impulse of 4 N s. What is its final speed?","explanation":"J = Δp = mv, so v = 4/0.5 = 8 m/s.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Impulse, Momentum and Centre of Mass","fingerprint":"1cc7a8a7cdb6864d0fbe920236122e361882cbdb17898901dbb26cca73d1525e","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Sessions 5 and 6","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Sessions 5 and 6","scientificallyCrossChecked":true},"options":[{"id":"3395379d-7f51-569a-b953-b69b161f8627","text":"8 m s⁻¹","isCorrect":true,"position":0},{"id":"cfc78fce-3c1d-5de9-8b30-fdfb1eaff082","text":"2 m s⁻¹","isCorrect":false,"position":1},{"id":"bed75f7f-8fa1-51de-ac10-086c77923861","text":"4.5 m s⁻¹","isCorrect":false,"position":2},{"id":"2e84e93c-93e7-550b-8a04-7d717e909211","text":"16 m s⁻¹","isCorrect":false,"position":3}]},{"id":"7a515159-45ee-5d55-a32a-44b4e133adfb","position":93,"prompt":"A 3 kg body moving at 4 m s⁻¹ east collides and sticks to a stationary 1 kg body. What is their common speed?","explanation":"Momentum conservation gives (3×4)/(3+1) = 3 m/s east.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Impulse, Momentum and Centre of Mass","fingerprint":"9ee4932cab5410a06adf07b214aedfb402ce79def6118d0df3da61ce2053fabd","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Sessions 5 and 6","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Sessions 5 and 6","scientificallyCrossChecked":true},"options":[{"id":"2473f578-38fd-5a29-98d9-5c6aee6e095e","text":"1 m s⁻¹ east","isCorrect":false,"position":0},{"id":"497d9dc5-3e3a-5cf6-bbac-1fdfeb775fd8","text":"4 m s⁻¹ east","isCorrect":false,"position":1},{"id":"f6779752-e9bc-55aa-89bf-ea8d5536ebed","text":"12 m s⁻¹ east","isCorrect":false,"position":2},{"id":"8694d0df-4110-57b1-9af3-4cff1775a635","text":"3 m s⁻¹ east","isCorrect":true,"position":3}]},{"id":"073a2d2e-049f-5887-b0d9-3f09806652cf","position":94,"prompt":"A 0.20 kg ball moving at 10 m s⁻¹ reverses at 5 m s⁻¹. What is the magnitude of its momentum change?","explanation":"Taking initial direction positive, Δp = 0.20(−5 − 10) = −3 kg·m/s; magnitude is 3.","questionKind":"calculation","difficulty":"hard","cognitive":"analysis","topic":"Impulse, Momentum and Centre of Mass","fingerprint":"61f5783e62c6a7e19b9d12762963a5d5d407b7459fe40ec64404db100126f0f6","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Sessions 5 and 6","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Sessions 5 and 6","scientificallyCrossChecked":true},"options":[{"id":"5620f3b8-d34e-50d9-a99a-35c1e1903550","text":"2 kg m s⁻¹","isCorrect":false,"position":0},{"id":"75816631-7b4f-5820-b134-5b43ce0df1b4","text":"15 kg m s⁻¹","isCorrect":false,"position":1},{"id":"398c650f-6171-5298-8328-1c1b9f573754","text":"3 kg m s⁻¹","isCorrect":true,"position":2},{"id":"9f7f5228-a26f-51e7-bd1e-d3d1026bcacc","text":"1 kg m s⁻¹","isCorrect":false,"position":3}]},{"id":"b000f76f-18cc-5a1b-a046-a80b22437d68","position":95,"prompt":"A 1000 kg car slows from 20 m s⁻¹ to rest in 5 s. What average braking force magnitude acts on it?","explanation":"F = Δp/Δt = (1000×20)/5 = 4000 N.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Impulse, Momentum and Centre of Mass","fingerprint":"7cf9e7c1e7da6177d903eff210989803a967d2b3cabbab5507503e202efffa53","studyRef":{"sourceLabel":"General PHY 101 enrichment: collisions, recoil and centre of mass","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: collisions, recoil and centre of mass","scientificallyCrossChecked":true},"options":[{"id":"6ff2b189-139b-5ee3-9368-80e778f7894a","text":"20,000 N","isCorrect":false,"position":0},{"id":"cb12fc2f-3852-5f65-92d1-9e2b40617920","text":"4000 N","isCorrect":true,"position":1},{"id":"ea52defc-c031-5300-b62c-5b85c63a8649","text":"200 N","isCorrect":false,"position":2},{"id":"5127684e-e426-5de8-aaf7-3275a6adef85","text":"1000 N","isCorrect":false,"position":3}]},{"id":"780f5b57-ceb2-5fec-8078-f4493d1d28d0","position":96,"prompt":"A 4 kg trolley moving at 5 m s⁻¹ collides elastically head-on with an identical stationary trolley. What happens ideally?","explanation":"In a one-dimensional elastic collision of equal masses, the velocities are exchanged.","questionKind":"analysis","difficulty":"hard","cognitive":"analysis","topic":"Impulse, Momentum and Centre of Mass","fingerprint":"f199eb2be503eefd5a4278ab5d8ffa43c81dd7cc09fd335488a91a3b846dee3e","studyRef":{"sourceLabel":"General PHY 101 enrichment: collisions, recoil and centre of mass","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: collisions, recoil and centre of mass","scientificallyCrossChecked":true},"options":[{"id":"c93b689f-cdec-54d4-8da0-9d33dd818d7e","text":"The first stops and the second moves at 5 m s⁻¹","isCorrect":true,"position":0},{"id":"84b67f6b-8b61-5e24-be97-e41b7c160803","text":"Both stick and move at 2.5 m s⁻¹","isCorrect":false,"position":1},{"id":"9eb9fbf8-ac17-5b1b-9b49-39f623addf97","text":"Both remain stationary","isCorrect":false,"position":2},{"id":"ad8b56de-7b7c-59b8-8c05-db8c5bb80a23","text":"The first rebounds at 5 m s⁻¹ while the second stays still","isCorrect":false,"position":3}]},{"id":"f8c6303f-c9a0-59f1-9c89-c123dc6c81a1","position":97,"prompt":"A 60 kg skater at rest throws a 3 kg bag east at 8 m s⁻¹. What is the skater's recoil velocity?","explanation":"Initial momentum is zero: 60v + 3(8) = 0, so v = −0.4 m/s.","questionKind":"calculation","difficulty":"hard","cognitive":"analysis","topic":"Impulse, Momentum and Centre of Mass","fingerprint":"bae9b395bcef53c584914a09a55abed7d9597e2bf3b214977385a379a419a113","studyRef":{"sourceLabel":"General PHY 101 enrichment: collisions, recoil and centre of mass","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: collisions, recoil and centre of mass","scientificallyCrossChecked":true},"options":[{"id":"c747e403-b2e7-531a-b935-9640f649ad2c","text":"0.4 m s⁻¹ east","isCorrect":false,"position":0},{"id":"dcb2a461-fd10-557a-a965-882251af611b","text":"2.5 m s⁻¹ west","isCorrect":false,"position":1},{"id":"c1297349-3be0-5356-9bbd-826769f05180","text":"24 m s⁻¹ west","isCorrect":false,"position":2},{"id":"d410f568-a4db-54ca-ba4e-e5f2bc0dba1a","text":"0.4 m s⁻¹ west","isCorrect":true,"position":3}]},{"id":"4ed7687a-1bc6-5a7a-9c95-12a898aadf18","position":98,"prompt":"Masses 2 kg and 6 kg lie at x = 0 m and x = 4 m respectively. Where is their centre of mass?","explanation":"xcm = (2×0 + 6×4)/(2+6) = 24/8 = 3 m.","questionK