66b3","text":"50 N s","isCorrect":false,"position":3}]},{"id":"582b87ee-8a19-56c3-8238-b4e94a3f5a9d","position":100,"prompt":"Mechanical work is done by a force when the force causes what?","explanation":"Work is the dot product F·s and requires displacement along a force component.","questionKind":"concept","difficulty":"medium","cognitive":"application","topic":"Work, Energy and Power","fingerprint":"6f79e8bdbfe94cf1106e8c65a2b7c7f84b02878728fac79e15a00cd156583124","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 7","scientificallyCrossChecked":true},"options":[{"id":"f8fae24e-c8c7-5b39-9314-d2ccb084adbc","text":"A displacement with a component along the force","isCorrect":true,"position":0},{"id":"19ce56ee-d9fd-5de4-82a6-364829c5dc89","text":"A temperature change only","isCorrect":false,"position":1},{"id":"89cea79f-47ec-540f-941e-33126e18bb65","text":"An increase in mass","isCorrect":false,"position":2},{"id":"3bb5b810-c935-54e9-8863-2b847b17a317","text":"An object to remain fixed","isCorrect":false,"position":3}]},{"id":"6e7622c9-6128-5277-b179-6c24aa84b870","position":101,"prompt":"What is the SI unit of work and energy?","explanation":"The joule is equal to one newton metre.","questionKind":"recall","difficulty":"easy","cognitive":"recall","topic":"Work, Energy and Power","fingerprint":"bb5eaad4dcf15276f1f9cce7f02458e6d03cf43ae18adfca1b53baf5d6c168dd","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 7","scientificallyCrossChecked":true},"options":[{"id":"e63a0a70-f57a-54db-b6de-1ba1653da30f","text":"watt","isCorrect":false,"position":0},{"id":"dfb32224-5ec2-53a1-8b91-89bf08419402","text":"newton","isCorrect":false,"position":1},{"id":"2fc4f8b0-db46-5bac-b8c4-fa34be55e5ed","text":"pascal","isCorrect":false,"position":2},{"id":"44a03e8c-e589-5bc9-9abb-924038c6cb8c","text":"joule","isCorrect":true,"position":3}]},{"id":"8fc5e6af-d432-5285-84f2-62f59ff271e0","position":102,"prompt":"Power is defined as the rate of doing what?","explanation":"Power is work done or energy transferred per unit time.","questionKind":"recall","difficulty":"easy","cognitive":"recall","topic":"Work, Energy and Power","fingerprint":"7f0bbbf93d1e1d9090eb69d1b0df8186c628ba8a1d7e39a08d230535ecb8b212","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 7","scientificallyCrossChecked":true},"options":[{"id":"d6889a9a-9d48-5d84-a552-f85c2beecd37","text":"mass","isCorrect":false,"position":0},{"id":"83e12874-a11b-5283-bb4f-4781d6a9fd64","text":"displacement only","isCorrect":false,"position":1},{"id":"ef5ca2d3-72f3-51f4-9640-0199f4c93d15","text":"work","isCorrect":true,"position":2},{"id":"47bf00a1-fbe6-55c8-8d4e-e4520b0eb3a5","text":"momentum","isCorrect":false,"position":3}]},{"id":"4e3d7a24-cd27-56be-a404-6130b7b150a9","position":103,"prompt":"When is the work done by a constant force zero?","explanation":"W = Fs cos θ; at θ = 90°, cos θ = 0.","questionKind":"concept","difficulty":"medium","cognitive":"application","topic":"Work, Energy and Power","fingerprint":"6d0bf0ffb5edf260d5c247cc0ae0c03d0e6d8267540053609b8493ebfafb73b0","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 7","scientificallyCrossChecked":true},"options":[{"id":"7abc78ce-a80c-5b41-b3aa-1d93107f0976","text":"Whenever the force is larger than the weight","isCorrect":false,"position":0},{"id":"7e