":3}]},{"id":"7a79a8c3-9bb5-5ecb-b914-d14cdd424739","position":111,"prompt":"What is the kinetic energy of a 2 kg object moving at 5 m s⁻¹?","explanation":"K = ½mv² = 0.5 × 2 × 25 = 25 J.","questionKind":"calculation","difficulty":"easy","cognitive":"recall","topic":"Work, Energy and Power","fingerprint":"0d04377a6692ccd502e1ce0df64c57084289219d0d2ccefef8bbd0f6f2bf48f1","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 7","scientificallyCrossChecked":true},"options":[{"id":"feb3c372-0e7d-5e95-9bfd-033f2fd41eb0","text":"50 J","isCorrect":false,"position":0},{"id":"51925f4b-5ad9-54eb-8683-8bd11f617416","text":"25 J","isCorrect":true,"position":1},{"id":"0a2bc878-be0f-5994-bfac-6b42427ca75a","text":"10 J","isCorrect":false,"position":2},{"id":"7b7abb7a-e494-5163-8e5b-353e436b1151","text":"20 J","isCorrect":false,"position":3}]},{"id":"f0c9b26e-02e1-5368-a6b5-12b8651092ef","position":112,"prompt":"Taking g = 10 m s⁻², what gravitational potential energy does a 3 kg mass gain when raised 5 m?","explanation":"ΔU = mgh = 3 × 10 × 5 = 150 J.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Work, Energy and Power","fingerprint":"93584ec5b32918b44fcede9b3db5a100688104e203d2cf90ca1adf28a3e640c5","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 7","scientificallyCrossChecked":true},"options":[{"id":"3cb6d386-43c6-53c4-bf73-bed1adeaccb9","text":"150 J","isCorrect":true,"position":0},{"id":"efa7b4ce-037f-595f-ac88-d87eaa953311","text":"15 J","isCorrect":false,"position":1},{"id":"d8d7eac9-71d4-5a31-b2d5-35654bea51a1","text":"50 J","isCorrect":false,"position":2},{"id":"8c8d5a9e-ecbb-59a5-9c35-0958e926be6b","text":"300 J","isCorrect":false,"position":3}]},{"id":"36094352-f847-5f5c-9dc7-b9c6034abdbe","position":113,"prompt":"A motor does 2400 J of work in 8 s. What is its average power?","explanation":"P = W/t = 2400/8 = 300 W.","questionKind":"calculation","difficulty":"easy","cognitive":"recall","topic":"Work, Energy and Power","fingerprint":"23f8d184a96accf2a4241d1f8204c47d6651da65f0bc5fffc7a0b8699421009b","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 7","scientificallyCrossChecked":true},"options":[{"id":"02d24d5e-6ee3-5957-a675-a07036ed47ff","text":"30 W","isCorrect":false,"position":0},{"id":"a202db6b-1b9c-5e39-a658-a78fa5ee1029","text":"192 W","isCorrect":false,"position":1},{"id":"839aadec-b82b-5ab2-b575-a49d4bb2c113","text":"19,200 W","isCorrect":false,"position":2},{"id":"a02366f3-2597-5d12-92b1-ef6fa888db05","text":"300 W","isCorrect":true,"position":3}]},{"id":"6a0c6eb0-4c8c-519c-b6cb-8ec0a62484c1","position":114,"prompt":"A 50 N force moves a body 6 m at 60° to the force direction. What work is done?","explanation":"W = Fs cos 60° = 50 × 6 × 0.5 = 150 J.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Work, Energy and Power","fingerprint":"7586c0abe739de98879c750864fa6b6fd6c9fabb9b3407a38fc9144d6d2936ad","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 7","scientificallyCrossChecked":true},"options":[{"id":"6b93872d-ebb1-5b4a-ab1d-88b5bc2f03c6","text":"300 J","isCorrect":false,"position":0},{"id":"ab998abe-08dc-517e-82a5-acff739416a8","text":"600 J","isCorrect":false,"position":1},{"id":"f77ad757-0142-5d47-bf0c-954f95e96192","text":"150 J","isCorrect":true,"