LocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: energy conservation and efficiency","scientificallyCrossChecked":true},"options":[{"id":"c26e7003-96a1-5da2-968f-1705f7d2bc1a","text":"500 W","isCorrect":false,"position":0},{"id":"6786baa6-7087-52f3-bd31-16a8da8defb2","text":"4000 W","isCorrect":false,"position":1},{"id":"086b9171-db56-5e6e-9e3c-f29449198b43","text":"400 W","isCorrect":true,"position":2},{"id":"3da3cd27-9d6f-5504-b3a9-84001ee425a7","text":"40 W","isCorrect":false,"position":3}]},{"id":"4060045d-8d4b-5c65-bd16-34a35cd64937","position":119,"prompt":"A stone falls freely from a height of 20 m. Ignoring air resistance and taking g = 10 m s⁻², what is its speed just before impact?","explanation":"mgh = ½mv² gives v = √(2gh) = √400 = 20 m/s.","questionKind":"calculation","difficulty":"hard","cognitive":"analysis","topic":"Work, Energy and Power","fingerprint":"10076b58c6c6fa0c759e9e206312f30994eb7136d6cb7e7c54389de7a7467b34","studyRef":{"sourceLabel":"General PHY 101 enrichment: energy conservation and efficiency","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: energy conservation and efficiency","scientificallyCrossChecked":true},"options":[{"id":"0da47553-c139-5d6f-a08b-e388e05c12f0","text":"200 m s⁻¹","isCorrect":false,"position":0},{"id":"4e20f89b-297b-5f9b-86d3-52c1f3f5bcd6","text":"20 m s⁻¹","isCorrect":true,"position":1},{"id":"b82ad459-5ada-579a-b868-7c60dab0bb7f","text":"10 m s⁻¹","isCorrect":false,"position":2},{"id":"7f9f7201-a81f-52fc-951e-3b93d1d3c21a","text":"40 m s⁻¹","isCorrect":false,"position":3}]},{"id":"b50c232e-0c9a-50fc-b0a3-84b825171151","position":120,"prompt":"In uniform circular motion, the instantaneous velocity is directed how?","explanation":"Velocity is tangent to the path while centripetal acceleration points inward.","questionKind":"concept","difficulty":"medium","cognitive":"application","topic":"Circular Motion","fingerprint":"1d29351ddeed891e9c102f89ba2493a93248e2547b8804cb694f92516b2d3080","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 8","scientificallyCrossChecked":true},"options":[{"id":"0e043757-8e97-55ea-81a8-bfcf563c3744","text":"Tangentially to the circular path","isCorrect":true,"position":0},{"id":"a289e524-4c36-5add-9b90-f9a74cb29599","text":"Radially toward the centre","isCorrect":false,"position":1},{"id":"1405e11b-ef10-54c9-9007-9fb67a0d51ef","text":"Radially away from the centre","isCorrect":false,"position":2},{"id":"7afc442c-b210-55d6-9ad7-0dac92bc0755","text":"Parallel to the rotation axis","isCorrect":false,"position":3}]},{"id":"9aacec81-676c-5a1d-88a2-377f32829036","position":121,"prompt":"What is the direction of centripetal acceleration?","explanation":"Centripetal means centre-seeking.","questionKind":"recall","difficulty":"easy","cognitive":"recall","topic":"Circular Motion","fingerprint":"25a147d8e204b417031fb6ea569efb1a3521e3f0c29ca498de2cd543b3e46d07","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 8","scientificallyCrossChecked":true},"options":[{"id":"5b9cf517-7c25-50fd-88a8-e1f6272fd407","text":"Tangential to the path","isCorrect":false,"position":0},{"id":"72e46586-3a43-53a0-996c-ef90354fc100","text":"Away from the centre","isCorrect":false,"position":1},{"id":"407b9208-d551-591a-b5aa-fab0250aaa7a","text":"Opposite the angular velocity","isCorrect":false,"position":2},{"id":"799a6cf5-d25e-50d3-be0c-b428b253ae88","text":"Toward the centre of the circle","isCorrect":true,"position":3}]},{"id":"06758217-8056-5985-8b1b-68e0ab27e4fa","position":122,"prompt":"Which expression gives centripetal acceleration?","explanation":"For speed v on a circle of radius r, ac = v²/r.","questionKind":"recall","difficulty":"easy","cognitive":"recall","topic":"Circular Motion","fingerprint":"392fb59ddd091db0a6f48b4566016caea575675c8de10e2fcf5a888a7fb66ed6","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 8","scientificallyCrossChecked":true},"options":[{"id":"289a0008-b566-5dc1-bfa6-52d687990900","text":"v/r²","isCorrect":false,"position":0},{"id":"17d55322-bfda-58a4-a3c6-d6e2278eef41","text":"r²/v","isCorrect":false,"position":1},{"id":"6cb6d3db-bd9b-5298-acda-d9f80964b3e4","text":"v²/r","isCorrect":true,"position":2},{"id":"9881e418-cd8b-5cb9-8455-2986317b4a8b","text":"vr","isCorrect":false,"position":3}]},{"id":"8f2e4ae8-6f83-50c5-9b07-fe75a2689cc2","position":123,"prompt":"How are angular speed ω and period T related?","explanation":"One revolution is 2π radians completed in time T.","questionKind":"recall","difficulty":"easy","cognitive":"recall","topic":"Circular Motion","fingerprint":"936af74231e9e670de9b5bb8612e8d5097b6718bd944e11844385e1fce0aeae2","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 8","scientificallyCrossChecked":true},"options":[{"id":"9bbcf982-5ee1-5e0c-8a90-33ffeada66d7","text":"ω = 1/(2πT)","isCorrect":false,"position":0},{"id":"903d00fd-eae6-530d-8185-577ec267a588","text":"ω = 2π/T","isCorrect":true,"position":1},{"id":"29c42c26-f813-5503-90b3-c9ac499057ca","text":"ω = T/2π","isCorrect":false,"position":2},{"id":"523d2fc8-26db-577e-8447-27fb7b535861","text":"ω = 2πT","isCorrect":false,"position":3}]},{"id":"960149cb-ebb7-52a0-81d4-651fbd