ext":"speed","isCorrect":true,"position":3}]},{"id":"4633ae17-7fcb-5452-97e4-37cdc176a987","position":126,"prompt":"The centripetal force on a satellite in circular orbit is supplied by what?","explanation":"Gravitational attraction provides the inward force needed for orbit.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Circular Motion","fingerprint":"c2a0646383dc529bd99ced9c5cd79eeccaf51cecab5bbd37888d5e54e0cf7704","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 8","scientificallyCrossChecked":true},"options":[{"id":"f8db85c3-9f3a-5d5e-acd9-d1eb913245f6","text":"magnetic attraction","isCorrect":false,"position":0},{"id":"a8e74755-2a91-5b54-acbe-5b4c6d42fb14","text":"atmospheric pressure","isCorrect":false,"position":1},{"id":"84a45e26-e58e-5111-a729-3200ccca9847","text":"gravity","isCorrect":true,"position":2},{"id":"52df2603-f41d-5284-9a80-2351244eee97","text":"engine thrust at all times","isCorrect":false,"position":3}]},{"id":"e74794ba-f4e9-5056-9ac9-b27f135966d2","position":127,"prompt":"If the speed of an object in a fixed-radius circle doubles, its centripetal force becomes what?","explanation":"Fc = mv²/r, so doubling v multiplies force by 2² = 4.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Circular Motion","fingerprint":"9de97b84cc0f4cf82d36ed26a4ea7ff10e0d5ae5737f61b814a75450a68f7975","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 8","scientificallyCrossChecked":true},"options":[{"id":"1b5ae9ff-bbe2-5a78-9709-f534395114b9","text":"Eight times as large","isCorrect":false,"position":0},{"id":"6a54ad0b-c7cd-514d-8237-a78f6c1aed40","text":"Four times as large","isCorrect":true,"position":1},{"id":"e22d01dd-7517-5604-925e-7c9c3291f328","text":"Half as large","isCorrect":false,"position":2},{"id":"d0f037d0-12a9-501c-a4f2-0b92a0fa575b","text":"Twice as large","isCorrect":false,"position":3}]},{"id":"22bf327e-99d9-5dcf-ad70-5ca8ee58ed89","position":128,"prompt":"A stone moving in a circle is released from its string. What path does it initially follow?","explanation":"Without the inward tension, inertia carries the stone along the instantaneous tangent.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Circular Motion","fingerprint":"b458ac0e757b89c6d7fd16fddfa452c8080f8abb41fd8617c904763edac95a66","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 8","scientificallyCrossChecked":true},"options":[{"id":"988a3fa8-d7b1-5392-8734-c13033e98586","text":"A straight line tangent to the circle","isCorrect":true,"position":0},{"id":"35f9fd29-0c4b-5b69-9ad8-78048c410eb2","text":"A radial line toward the centre","isCorrect":false,"position":1},{"id":"32ecf2af-c42e-5961-a4f5-05c6aa8b9ecc","text":"A radial line away from the centre","isCorrect":false,"position":2},{"id":"9612c44c-d071-50a2-b570-1208c03a58ad","text":"The same circle indefinitely","isCorrect":false,"position":3}]},{"id":"a8f38354-1fc5-5076-8022-b8520064d316","position":129,"prompt":"Which statement about centripetal force is correct?","explanation":"Tension, gravity, friction or another real force can provide the required net inward force.","questionKind":"analysis","difficulty":"hard","cognitive":"analysis","topic":"Circular Motion","fingerprint":"38fec8ce242fef242bb1b6ba6e556b3380d068818e2cdfe368e000bc59ef6fd9","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 8","scientificallyCrossChecked":true},"options":[{"id":"ca903308-4bd9-5850-99a7-e464ba9b3c28","text":"It always acts outward","isCorrect":false,"position":0},{"id":"179fe5f4-378a-58a4-bb4d-a63861bce4a1","text":"It exists only for planets","isCorrect":false,"position":1},{"id":"27481242-72b2-5c79-8242-264fdfe65dee","text":"It is always provided by friction","isCorrect":false,"position":2},{"id":"1f50a981-11e5-5709-a21d-b4678b4e0969","text":"It is the name for the net inward force, not a new type of interaction","isCorrect":true,"position":3}]},{"id":"cb9dbc32-3445-5b79-b3dc-fae57c65d535","position":130,"prompt":"A wheel completes 5 revolutions each second. What is its frequency?","explanation":"Frequency is the number of complete revolutions per second.","questionKind":"calculation","difficulty":"easy","cognitive":"recall","topic":"Circular Motion","fingerprint":"bd630246836e2d6612844fdcded51ede64000d37edba2f270d4e7301a6744e2f","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 8","scientificallyCrossChecked":true},"options":[{"id":"9e1cb12a-6be9-5bff-b9f9-8c5bd39c85ad","text":"10 Hz","isCorrect":false,"position":0},{"id":"233bdc0f-0a20-5b1d-9a2c-f93be781a4bf","text":"5 rad s⁻¹","isCorrect":false,"position":1},{"id":"f9fd79af-4f19-5ac1-85fe-f77fd3f9cb8b","text":"5 Hz","isCorrect":true,"position":2},{"id":"d875ebbc-225b-5b5a-a94f-6ccd439f894c","text":"0.2 Hz","isCorrect":false,"position":3}]},{"id":"057040f6-5dd3-5b8a-b61b-a3622408732b","position":131,"prompt":"An object moves in a circle of radius 2 m at 6 m s⁻¹. What is its centripetal acceleration?","explanation":"ac = v²/r = 36/2 = 18 m/s².","questionKind":"calculation","difficulty":"easy","cognitive":"recall","topic":"Circular Motion","fingerprint":"f603453c7f5a6dcd5ff1490d731d34364c9585e7388b1200f163203d07591da3","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 8","scientificallyCrossChecked":true},"options":[{"id":"5b8c9274-6066-5010-9324-ea7569157162","text":"72 m s⁻²","isCorrect":false,"position":0},{"id":"e350aca5-a80e-539a-a52e-16e3b2a005e1","text":"18 m s⁻²","isCorrect":true,"position":1},{"id":"0f5f3193-6d02-5278-b02b-6d815c2529f9","text":"3 m s⁻²","isCorrect":false,"position":2},{"id":"03754010-3f25-570c-9239-0b67d0f62256","text":"12 m s⁻²","isCorrect":false,"position":3}]},{"id":"e540ce27-32b1-5879-9035-7774a56e7cd1","position":132,"prompt":"A 3 kg body travels at 4 m s⁻¹ around a circle of radius 2 m. What centripetal force is required?","explanation":"Fc = mv²/r = 3 × 16 / 2 = 24 N.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Circular Motion","fingerprint":"48a728e110813337c6dfba9cc046d7d431559c4c6b7d114eda2ae29d48ae77a4","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 8","scientificallyCrossChecked":true},"options":[{"id":"e5e08703-9379-5883-a2a4-4c524287d5a4","text":"24 N","isCorrect":true,"position":0},{"id":"641f7f2a-07db-5059-83da-ee34b68c61c8","text":"6 N","isCorrect":false,"position":1},{"id":"eb570c29-b773-513d-9bd8-ed50ef69cd86","text":"12 N","isCorrect":false,"position":2},{"id":"5e128769-212e-5643-a70f-4b8dd4b707f2","text":"48 N","isCorrect":false,"position":3}]},{"id":"3edc8ba9-4f20-570a-83dc-bf1278b74e47","position":133,"prompt":"A particle has period 0.25 s. What is its frequency?","explanation":"f = 1/T = 1/0.25 = 4 Hz.","questionKind":"calculation","difficulty":"easy","cognitive":"recall","topic":"Circular Motion","fingerprint":"7559874dfb870beb7c1194cad47bd2dc60f36b20b59c7ce38a521058e544f51f","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 8","scientificallyCrossChecked":true},"options":[{"id":"f4c804ce-123b-5231-a1c5-350d132987d8","text":"0.25 Hz","isCorrect":false,"position":0},{"id":"3e31465c-73e2-5055-aad6-a5481ef4b6b1","text":"2 Hz","isCorrect":false,"position":1},{"id":"ec53e51d-8e44-5867-b7ec-a0c96ce9e87c","text":"8 Hz","isCorrect":false,"position":2},{"id":"352d8ff0-73f0-548f-ae74-0e9be937ab7c","text":"4 Hz","isCorrect":true,"position":3}]},{"id":"48b177a3-fc3b-58e8-aba9-7225d189206f","position":134,"prompt":"A rotating body has frequency 2 Hz. What is its angular speed?","explanation":"ω = 2πf = 2π × 2 = 4π rad/s.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Circular Motion","fingerprint":"32b8e6d411acddd569ea08ecd5d8a27b6b245cb7a8ae0e062b830a67b2609871","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 8","scientificallyCrossChecked":true},"options":[{"id":"dfba5486-a509-5ed5-ab9c-4da1370cef3b","text":"2π rad s⁻¹","isCorrect":false,"position":0},{"id":"db4c2d40-2ab4-5564-9af6-007581647d2e","text":"8π rad s⁻¹","isCorrect":false,"position":1},{"id":"c63fb3f8-e022-5819-b7ae-3a148739f7c5","text":"4π rad s⁻¹","isCorrect":true,"position":2},{"id":"0b07aee0-d5e9-5a07-b142-9826f9287b3d","text":"π rad s⁻¹","isCorrect":false,"position":3}]},{"id":"003760ef-8117-56a2-8f72-1342db998634","position":135,"prompt":"A car rounds a flat curve of radius 50 m at 10 m s⁻¹. What centripetal acceleration does it have?","explanation":"ac = v²/r = 100/50 = 2 m/s².","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Circular Motion","fingerprint":"4b0ba384b60166c4cdb7ffa782380aa387c07c52ca9b1f0e20f49e2f5a4f2b0d","studyRef":{"sourceLabel":"General PHY 101 enrichment: banking and vertical circles","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: banking and vertical circles","scientificallyCrossChecked":true},"options":[{"id":"d508f2f3-b8da-5597-8f1c-1d6d8fc0e13c","text":"20 m s⁻²","isCorrect":false,"position":0},{"id":"f890ba58-99eb-50bd-8869-084491c8e274","text":"2 m s⁻²","isCorrect":true,"position":1},{"id":"788f25a9-d536-5702-879b-41307cbbf913","text":"0.2 m s⁻²","isCorrect":false,"position":2},{"id":"90c4b100-54a0-5414-beb6-76f62109abeb","text":"5 m s⁻²","isCorrect":false,"position":3}]},{"id":"416b2012-1368-5e78-a56c-65d64ca7c4fe","position":136,"prompt":"A 0.50 kg mass moves in a horizontal circle of radius 0.80 m at 4 m s⁻¹. What inward tension is required?","explanation":"T = mv²/r = 0.5 × 16 / 0.8 = 10 N.","questionKind":"calculation","difficulty":"hard","cognitive":"analysis","topic":"Circular Motion","fingerprint":"872a8f84ec32376915edabe66bb456ad5fb6b404bb55dde3feb4e60dade20794","studyRef":{"sourceLabel":"General PHY 101 enrichment: banking and vertical circles","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: banking and vertical circles","scientificallyCrossChecked":true},"options":[{"id":"b4d81cdc-2dde-5b61-88f1-07f9b462daae","text":"10 N","isCorrect":true,"position":0},{"id":"f8d12ef3-555e-505b-bc02-c7dffdbf2e5c","text":"2.5 N","isCorrect":false,"position":1},{"id":"480bc0c3-33bd-508c-a5c0-f85ed78a6123","text":"4 N","isCorrect":false,"position":2},{"id":"c2f22cd7-0a94-539f-abf8-2af4403b023d","text":"16 N","isCorrect":false,"position":3}]},{"id":"8652e316-45d7-53e4-af59-6c8aec7d2399","position":137,"prompt":"A wheel of radius 0.50 m rotates at 6 rad s⁻¹. What is the speed of a point on its rim?","explanation":"Linear rim speed v = ωr = 6 × 0.5 = 3 m/s.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Circular Motion","fingerprint":"bf86de0b4c44c41de1c719196b4228b2f8ac6bf3c97b765044616f31da7333d6","studyRef":{"sourceLabel":"General PHY 101 enrichment: banking and vertical circles","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: banking and vertical circles","scientificallyCrossChecked":true},"options":[{"id":"60919d0b-b871-5bd6-a59d-91b0b5a0777a","text":"0.083 m s⁻¹","isCorrect":false,"position":0},{"id":"04009b18-37d9-58e9-993a-d86eb6e31bae","text":"6.5 m s⁻¹","isCorrect":false,"position":1},{"id":"e80a18e5-bb0e-5af3-9929-432cc8461714","text":"12 m s⁻¹","isCorrect":false,"position":2},{"id":"71337299-b247-5460-bee8-0cf81ad43a05","text":"3 m s⁻¹","isCorrect":true,"position":3}]},{"id":"dc6b2b07-3f7a-57cc-8e66-8a5599a7dd81","position":138,"prompt":"A 1000 kg car rounds a 25 m radius bend at 5 m s⁻¹. What horizontal friction force supplies the centripetal force?","explanation":"F = mv²/r = 1000 × 25 / 25 = 1000 N.","questionKind":"calculation","difficulty":"hard","cognitive":"analysis","topic":"Circular Motion","fingerprint":"195d1062a7c4a214836da158cfb2ab0a1ad80283d7d5d6ed3363810a851854aa","studyRef":{"sourceLabel":"General PHY 101 enrichment: banking and vertical circles","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: banking and vertical circles","scientificallyCrossChecked":true},"options":[{"id":"fb288a10-5a57-5f88-bc5b-57e69e21ecce","text":"5000 N","isCorrect":false,"position":0},{"id":"80131056-9d30-5f69-80c0-a0c05f51c6d0","text":"25,000 N","isCorrect":false,"position":1},{"id":"bf00a9ff-fbba-546e-96b7-704e1a6c5f19","text":"1000 N","isCorrect":true,"position":2},{"id":"b35d8e11-e00a-5759-865f-5d45574c8458","text":"200 N","isCorrect":false,"position":3}]},{"id":"15131e8a-1d5e-5440-900c-d22eed683496","position":139,"prompt":"At the top of a vertical circle, the minimum speed condition for a string to remain just taut is v²/r equal to what?","explanation":"At the limiting condition tension is zero and gravity alone supplies mv²/r, so v²/r = g.","questionKind":"analysis","difficulty":"hard","cognitive":"analysis","topic":"Circular Motion","fingerprint":"f6326814b7f4d9d77e5cf2a7d653386d57362b8f59e0fb15cf86ecba86c5dc68","studyRef":{"sourceLabel":"General PHY 101 enrichment: banking and vertical circles","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: banking and vertical circles","scientificallyCrossChecked":true},"options":[{"id":"346acf93-5842-58fe-b00a-5324857ddf27","text":"g/2","isCorrect":false,"position":0},{"id":"3233f951-9458-59d4-967b-a6a5871718fe","text":"g","isCorrect":true,"position":1},{"id":"1083cc9e-3ef8-594f-93fb-3640e8ec3d19","text":"0","isCorrect":false,"position":2},{"id":"c6e4bfb7-6dc1-5ff9-91ed-acac54d55974","text":"2g","isCorrect":false,"position":3}]},{"id":"6921c239-d697-518c-b412-fffd6165e086","position":140,"prompt":"A motion is simple harmonic when acceleration is proportional to displacement and directed how?","explanation":"SHM satisfies a = −ω²x; the minus sign indicates acceleration toward equilibrium.","questionKind":"concept","difficulty":"medium","cognitive":"application","topic":"Simple Harmonic Motion","fingerprint":"25868e7369aad7efad09b474fe8232289bca67c94296d1b7d0f120b1c57ddd2c","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","scientificallyCrossChecked":true},"options":[{"id":"5e535389-3594-5f72-9a28-95e59779eb10","text":"Opposite to the displacement","isCorrect":true,"position":0},{"id":"b6edcdaf-c4bb-52bb-9c47-6c889b56c97e","text":"Along the displacement","isCorrect":false,"position":1},{"id":"3f748cbd-c893-59a4-815d-7b9e5a72f967","text":"Perpendicular to the displacement","isCorrect":false,"position":2},{"id":"05473dc1-541b-5e44-8782-732d4fedb061","text":"Randomly at every point","isCorrect":false,"position":3}]},{"id":"e185506f-7cdc-579d-b7b6-2926497e0ad2","position":141,"prompt":"At the equilibrium position in ideal SHM, the speed is what?","explanation":"Potential energy is minimum and kinetic energy, hence speed, is maximum at equilibrium.","questionKind":"concept","difficulty":"medium","cognitive":"application","topic":"Simple Harmonic Motion","fingerprint":"b4d88594a4dabce90dfbd415a18b0de57cade558bb89866c7a9b139c119ef5cb","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","scientificallyCrossChecked":true},"options":[{"id":"54649c5e-e6f6-5831-94d8-3560c4324c15","text":"Zero","isCorrect":false,"position":0},{"id":"55fb3926-73be-532a-a167-8da90e1d60d9","text":"Always negative","isCorrect":false,"position":1},{"id":"b775a182-c5a4-5a09-8ee8-dc21c96016b6","text":"Equal to the amplitude","isCorrect":false,"position":2},{"id":"ef83bc7e-91a7-50bd-b6ae-d0031cd948e3","text":"Maximum","isCorrect":true,"position":3}]},{"id":"df771367-dd0f-50d1-92a2-4eb45bb42e9c","position":142,"prompt":"At an extreme position in SHM, the instantaneous velocity is what?","explanation":"The oscillator reverses direction at an extreme, so its instantaneous velocity is zero.","questionKind":"recall","difficu