t":false,"position":3}]},{"id":"f139cf8e-bf31-52f1-abb3-6860d32f93ab","position":144,"prompt":"What does the amplitude of an oscillation represent?","explanation":"Amplitude is the largest magnitude of displacement from the equilibrium position.","questionKind":"recall","difficulty":"easy","cognitive":"recall","topic":"Simple Harmonic Motion","fingerprint":"7a99239a2fadaa69e9156b77bf66f077cfc46cc379c07399111f92a2985fa1e7","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","scientificallyCrossChecked":true},"options":[{"id":"1cef6034-1e18-5445-9a41-18d2f4c366b9","text":"Maximum displacement from equilibrium","isCorrect":true,"position":0},{"id":"9f795fba-a04b-5b98-afda-b75febcd6dcf","text":"Total distance in one cycle","isCorrect":false,"position":1},{"id":"6a2ace94-f2cf-50cd-8846-d40b725ea0fb","text":"Time for one cycle","isCorrect":false,"position":2},{"id":"ffcacd4c-4161-5e20-bb39-bb57aa5d48b5","text":"Number of cycles per second","isCorrect":false,"position":3}]},{"id":"af6f71ca-f518-52b3-8630-6af820c27638","position":145,"prompt":"Which relation connects angular frequency and period in SHM?","explanation":"One cycle corresponds to 2π radians in time T.","questionKind":"recall","difficulty":"easy","cognitive":"recall","topic":"Simple Harmonic Motion","fingerprint":"43f57c3d7bfc4379b2447b5fe0f633dca596b31b3c646dbfa5a126bd12eecfd4","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","scientificallyCrossChecked":true},"options":[{"id":"0796ebe9-ea61-573a-ad92-df6e70cde278","text":"ω = T/2π","isCorrect":false,"position":0},{"id":"b63a3078-7004-5b9a-ad14-0ac8abbafab5","text":"ω = 1/T²","isCorrect":false,"position":1},{"id":"47c14275-65db-5238-a276-c932cf959900","text":"ω = 2πT","isCorrect":false,"position":2},{"id":"d443f3a9-7b85-58ac-b47e-c8ef40a023d1","text":"ω = 2π/T","isCorrect":true,"position":3}]},{"id":"0c2ed6cf-9032-5a5a-992d-3904db2c55cb","position":146,"prompt":"For an ideal mass-spring oscillator, increasing the mass while keeping k fixed does what to the period?","explanation":"T = 2π√(m/k), so period increases with √m.","questionKind":"concept","difficulty":"medium","cognitive":"application","topic":"Simple Harmonic Motion","fingerprint":"95aee4550ebdc48ee93e35913fe3f909a03e3f46338a1b5e07343ca0bcaddaf9","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","scientificallyCrossChecked":true},"options":[{"id":"305f8f0d-f820-52e1-89e7-509d1fe621ac","text":"Leaves it unchanged","isCorrect":false,"position":0},{"id":"0f2d5c0f-2aef-5939-b128-c596d70ed718","text":"Makes it zero","isCorrect":false,"position":1},{"id":"e94d0769-90da-566f-b92c-b18f8df56faa","text":"Increases it","isCorrect":true,"position":2},{"id":"94b59202-9dfb-5849-ad72-781d5acb6ab8","text":"Decreases it","isCorrect":false,"position":3}]},{"id":"c8539b2f-9072-5653-a257-c7db018bee9e","position":147,"prompt":"For small oscillations, the period of a simple pendulum is independent of what?","explanation":"T = 2π√(L/g), which contains no bob mass.","questionKind":"concept","difficulty":"medium","cognitive":"application","topic":"Simple Harmonic Motion","fingerprint":"5134ba572b505c14cf56f0cb1560a461ef531a6757347b7000d6265566807e5c","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","scientificallyCrossChecked":true},"options":[{"id":"78105414-0a5f-5b29-be64-b80b11abf871","text":"The square root of length","isCorrect":false,"position":0},{"id":"cb1310c1-888c-5957-a605-8a82e0a1d73c","text":"The bob's mass","isCorrect":true,"position":1},{"id":"4252bda3-5729-5b32-a25e-6d517f99e721","text":"The pendulum length","isCorrect":false,"position":2},{"id":"d2f76454-4ab3-56c2-bce1-0f7ed28b008f","text":"Gravitational acceleration","isCorrect":false,"position":3}]},{"id":"f952ef67-1172-58f3-a88b-c622d195d7ff","position":148,"prompt":"At which SHM position is elastic potential energy greatest?","explanation":"Spring potential energy ½kx² is greatest at |x| = A.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Simple Harmonic Motion","fingerprint":"f03a8b4e92912ed4875eead30a82a90de9d70351355ee6790c178d199304a451","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","scientificallyCrossChecked":true},"options":[{"id":"85573dd7-b8e4-582f-b78c-c25a368a4a18","text":"At maximum displacement","isCorrect":true,"position":0},{"id":"1db8124f-dc9d-5474-901d-957b74700cbc","text":"At equilibrium","isCorrect":false,"position":1},{"id":"722bbf0d-dba3-5967-8b3c-34d478087861","text":"At zero acceleration","isCorrect":false,"position":2},{"id":"879d22fd-60e1-5b36-b9c3-82e28b94bd0e","text":"At maximum speed","isCorrect":false,"position":3}]},{"id":"f77b87ea-1933-5eb1-8ae3-7bc8f210dfae","position":149,"prompt":"What is the phase difference between displacement and acceleration in SHM?","explanation":"Since a = −ω²x, acceleration is exactly opposite in phase to displacement.","questionKind":"analysis","difficulty":"hard","cognitive":"analysis","topic":"Simple Harmonic Motion","fingerprint":"efa7a2771e381228e07cc0590298bc4b765908b965d68a901d2ba5e4a64ea231","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","scientificallyCrossChecked":true},"options":[{"id":"b68205f6-3519-5269-9b97-f57b2cac637d","text":"0 radians","isCorrect":false,"position":0},{"id":"b909d76e-3ba5-54f1-be9c-e164995f9b03","text":"π/2 radians","isCorrect":false,"position":1},{"id":"48619953-410a-5928-bdbb-79130bbcb839","text":"2π radians","isCorrect":false,"position":2},{"id":"a02bfb2f-0913-56d9-a588-293dc89d618f","text":"π radians","isCorrect":true,"position":3}]},{"id":"4b4d4296-44a9-5c3a-89ec-b9382359b195","position":150,"prompt":"An oscillator completes 30 cycles in 15 s. What is its frequency?","explanation":"f = number/time = 30/15 = 2 Hz.","questionKind":"calculation","difficulty":"easy","cognitive":"recall","topic":"Simple Harmonic Motion","fingerprint":"487e09ca0329cc5b5f10179868e376df68b1e31cd3f20af1a73715669d7c28d5","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","scientificallyCrossChecked":true},"options":[{"id":"633e5414-836b-5e2f-a4f1-eb0bb765264c","text":"15 Hz","isCorrect":false,"position":0},{"id":"aed10794-dd5f-583c-8853-6f881c6dde51","text":"450 Hz","isCorrect":false,"position":1},{"id":"cdd32917-860f-5847-abfc-644070f33272","text":"2 Hz","isCorrect":true,"position":2},{"id":"38d6c418-8d96-545b-9bd5-18be5203ceb6","text":"0.5 Hz","isCorrect":false,"position":3}]},{"id":"e43a9bcd-1e52-5a10-a7bd-047c45f57e13","position":151,"prompt":"An SHM oscillator has frequency 4 Hz. What is its period?","explanation":"T = 1/f = 1/4 = 0.25 s.","questionKind":"calculation","difficulty":"easy","cognitive":"recall","topic":"Simple Harmonic Motion","fingerprint":"b51fca9409b69d21320890384b1707d701d5537bf4335c2e0bf05f089f65c291","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","scientificallyCrossChecked":true},"options":[{"id":"66426464-e49b-543b-a4b9-9940cb19bede","text":"4 s","isCorrect":false,"position":0},{"id":"0094286d-d373-55a6-8feb-4e60b8b0ccef","text":"0.25 s","isCorrect":true,"position":1},{"id":"88f81243-4795-5773-9be5-01f0ea7013e0","text":"0.04 s","isCorrect":false,"position":2},{"id":"76626a0f-4e3f-58fa-8fc4-6fb389ae4fe3","text":"2 s","isCorrect":false,"position":3}]},{"id":"ad0089b0-b9eb-5a51-bde4-154be2c037f5","position":152,"prompt":"A mass-spring system has m = 2 kg and k = 50 N m⁻¹. What is its angular frequency?","explanation":"ω = √(k/m) = √(50/2) = √25 = 5 rad/s.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Simple Harmonic Motion","fingerprint":"a737ac9a34315f007f34d22197fa782abcae3eb6edabe1f4f1e66f50721340b8","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","scientificallyCrossChecked":true},"options":[{"id":"e3dd611e-8bb4-5dca-b503-8c5025063da1","text":"5 rad s⁻¹","isCorrect":true,"position":0},{"id":"0d7325cc-62a5-553d-89f1-2ad5002e4d34","text":"0.2 rad s⁻¹","isCorrect":false,"position":1},{"id":"667ea06b-c00e-5b3e-966f-dca7f633c8bd","text":"10 rad s⁻¹","isCorrect":false,"position":2},{"id":"966755ff-5162-549b-9577-8a353ab42973","text":"25 rad s⁻¹","isCorrect":false,"position":3}]},{"id":"71054685-f11f-5577-ab94-8f0d83dd8af1","position":153,"prompt":"An oscillator has amplitude 0.20 m and angular frequency 5 rad s⁻¹. What is its maximum speed?","explanation":"vmax = ωA = 5 × 0.20 = 1.0 m/s.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Simple Harmonic Motion","fingerprint":"2d002394e56088ba43c61edbad31afb4e81bbdfe02c54901ceede8fa3cf1a267","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","scientificallyCrossChecked":true},"options":[{"id":"ce0e3ec8-c717-5aaf-bbea-4b05411a9194","text":"0.04 m s⁻¹","isCorrect":false,"position":0},{"id":"cb5d5d38-3c0a-50b6-9178-6a3b9d45b740","text":"5.2 m s⁻¹","isCorrect":false,"position":1},{"id":"1c0ff13b-e4ba-5992-bd72-5d09962147ac","text":"25 m s⁻¹","isCorrect":false,"position":2},{"id":"2b789044-fa99-51cc-ae18-73d936afda96","text":"1.0 m s⁻¹","isCorrect":true,"position":3}]},{"id":"702d2b06-cc74-52ee-acb2-f745d6cc2586","position":154,"prompt":"An SHM particle has ω = 4 rad s⁻¹ and displacement x = 0.50 m. What is its acceleration?","explanation":"a = −ω²x = −16 × 0.50 = −8 m/s².","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Simple Harmonic Motion","fingerprint":"13422fb928d78c93ee5fa18d78796c7b0823aa5201e2d2f7971884db90d7f8ff","studyRef":{"sourceLabel":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"PHY 101 NOTE (1), Study Session 9; downloadfile (4), Chapter 2","scientificallyCrossChecked":true},"options":[{"id":"13b7225a-7d9a-5ffb-9536-9b3343e23cd0","text":"+8 m s⁻²","isCorrect":false,"position":0},{"id":"e9a71e35-adad-59cf-a73a-3f95411554c9","text":"+16 m s⁻²","isCorrect":false,"position":1},{"id":"d88fbe0f-0e4b-544b-ac14-b9d8485fc16a","text":"−8 m s⁻²","isCorrect":true,"position":2},{"id":"b4c8e634-e82f-5515-ae4f-7bc3547efe74","text":"−2 m s⁻²","isCorrect":false,"position":3}]},{"id":"af19302b-37b2-5c2c-bb76-e75f96b105a2","position":155,"prompt":"A spring of constant 100 N m⁻¹ oscillates with amplitude 0.10 m. What is its total mechanical energy?","explanation":"E = ½kA² = 0.5 × 100 × 0.10² = 0.50 J.","questionKind":"calculation","difficulty":"medium","cognitive":"application","topic":"Simple Harmonic Motion","fingerprint":"4d448d52949e3cd93f2b64adf3a244185cefdeac0b3593452518a628fcd015d8","studyRef":{"sourceLabel":"General PHY 101 enrichment: oscillator energy and pendulums","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: oscillator energy and pendulums","scientificallyCrossChecked":true},"options":[{"id":"333b5306-340d-5942-9808-79136d8b81e0","text":"10 J","isCorrect":false,"position":0},{"id":"3ef2f3b7-e98f-5f79-a005-52eb6fd43678","text":"0.50 J","isCorrect":true,"position":1},{"id":"090b0e22-ec1e-5478-ab36-2e23f2fd3ab4","text":"0.05 J","isCorrect":false,"position":2},{"id":"65bcf0f4-1b7b-57cf-bcf6-8f8dbfd82dd6","text":"1.0 J","isCorrect":false,"position":3}]},{"id":"1706b742-c89c-524b-a67e-24ae417225e8","position":156,"prompt":"A 1 kg mass on a spring has k = 4π² N m⁻¹. What is its period?","explanation":"T = 2π√(m/k) = 2π√(1/4π²) = 1 s.","questionKind":"calculation","difficulty":"hard","cognitive":"analysis","topic":"Simple Harmonic Motion","fingerprint":"8482cb3309b7d8a99d377884250d0589fc2cdd9309d8911620f54446cf4f50a3","studyRef":{"sourceLabel":"General PHY 101 enrichment: oscillator energy and pendulums","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: oscillator energy and pendulums","scientificallyCrossChecked":true},"options":[{"id":"bc900e75-dbca-516d-b004-e742ac2984cf","text":"1 s","isCorrect":true,"position":0},{"id":"5c939c2c-7b5f-5093-9255-4bbc37d4fe22","text":"0.5 s","isCorrect":false,"position":1},{"id":"bcb314c8-cbc5-5c0b-8728-ce852823408e","text":"2 s","isCorrect":false,"position":2},{"id":"10454797-b3aa-51d7-be2d-60bde66d1c82","text":"2π s","isCorrect":false,"position":3}]},{"id":"adc53664-78de-5ad6-8e24-e1d4e3055b86","position":157,"prompt":"Taking g = 10 m s⁻², what is approximately the period of a simple pendulum of length 1.0 m?","explanation":"T = 2π√(L/g) ≈ 2π/√10 ≈ 2.0 s.","questionKind":"calculation","difficulty":"hard","cognitive":"analysis","topic":"Simple Harmonic Motion","fingerprint":"ffbbac3f61bdfa82fba00aab3ba53399ac1c6c85f5e28681da04835c097fa1f4","studyRef":{"sourceLabel":"General PHY 101 enrichment: oscillator energy and pendulums","sourceKind":"general_phy101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_phy101_200_v1","sourceReference":"General PHY 101 enrichment: oscillator energy and pendulums","scientificallyCrossChecked":true},"options":[{"id":"e2dcaeaf-8fdd-5335-85aa-054916e8ee8c","text":"0.32 s","isCorrect":false,"position":0},{"id":"73b43414-a7c1-5dfa-aa43-54c745202fcc","text":"1.0 s","isCorrect":false,"position":1},{"id":"f6be45e1-a88a-58ef-95a2-80f0785b95f9","text":"6.3 s","isCorrect":false,"position":2},{"id":"f85319b2-f4d9-5f89-8c1f-54b76a342513","text":"2.0 s","isCorrect":true,"position":3}]},{"id":"1da2de13-a15b-592b-a13b-a3c55050368f","position":158,"prompt":"If a simple pendulum's length is increased by a factor of four, its small-angle period becomes what?","explanation":"T ∝ √L, so √4 = 2.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Simple Harmonic Motion","fingerprint":"95e88791ec8733932f8c